"""Add original interactive graphics and rich document editing tracks."""
import copy
import datetime
import html
import json
import re
import subprocess
import uuid
from pathlib import Path

root = Path(__file__).resolve().parents[1]
fixture = root / 'src/data/fixtures.json'
entries = json.loads(fixture.read_text())
by_path = {entry['path']: entry for entry in entries}
stamp = datetime.datetime.now(datetime.UTC).isoformat()

def p(value):
    return '<p>' + html.escape(value) + '</p>'

def link(path):
    assert path in by_path, path
    return '<a href="/' + html.escape(path, quote=True) + '">' + html.escape(by_path[path]['title']) + '</a>'

hubs = [
    dict(path='web-tech/interactive-graphics-and-canvas-boundaries', title='Interactive Graphics and Canvas Boundaries', summary='Choose a scene model, map coordinates, protect export, and expose graphic meaning beyond pixels.', overview='A graphic can be an image, a small set of meaningful vector objects, or a frequently redrawn bitmap. The choice changes hit testing, text alternatives, memory, and export behavior. This track follows an inspection map on which a reviewer marks damaged regions and exports an annotated copy. It covers SVG versus Canvas ownership, device-pixel scaling, pointer mapping, cross-origin image restrictions, and accessible controls. The scene data remains separate from pixels so it can be saved, tested, and described.', bridges=['web-tech/accessible-content-and-media','web-tech/browser-execution-and-resource-lifecycle']),
    dict(path='web-tech/rich-document-editing-and-safe-content', title='Rich Document Editing and Safe Content', summary='Keep editable content in a versioned model while handling composition, selection, paste, and undo.', overview='A rich editor is a document model with a browser input surface, not a contenteditable element alone. The browser may insert text, fragments, spell corrections, and composition updates through different paths. This track follows a private case note with headings and emphasis. It covers input and IME boundaries, selection positions across transforms, safe pasted content, bounded undo history, and revisioned autosave. The note remains usable as plain text when advanced formatting fails, and rendered output follows the same server-side content policy.', bridges=['web-tech/forms-and-data-entry-workflows','web-tech/browser-security-and-data-stewardship']),
]

topics = [
    dict(hub=0, slug='svg-canvas-scene-model-and-hit-testing', title='SVG, Canvas, Scene Model, and Hit Testing', summary='Choose DOM-backed shapes or a redrawn bitmap from interaction density and semantic needs.',
    concept='SVG retains elements in a document tree; Canvas draws pixels into a bitmap whose shapes are not separately remembered by the browser. That distinction determines how you update, focus, and hit-test an inspection map. SVG suits a bounded set of meaningful regions that need individual labels and controls. Canvas can suit a large, rapidly changing scene, but the application must own the scene graph, drawing order, hit testing, and text equivalent. Neither medium is a data model. Store marks as structured records outside the rendering layer.',
    case='Reviewer 29 opens case 62 with 47 annotated defect regions. Each region has an ID, severity, description, and geometry. At this density, the team renders an SVG overlay whose region controls can receive focus and expose meaningful names. A live sensor trace behind it redraws many times per second on a separate Canvas. Clicking either view selects a region ID in the case model. The saved record contains geometry and a note, not a screenshot of the overlay. When the sensor trace is unavailable, the region list still describes every action.',
    implementation='Count interactive shapes, update frequency, and labeling needs before choosing a renderer. Keep coordinates in an explicit world space and map to the rendered viewport. For SVG, delegate events to named region IDs and provide keyboard paths; avoid one event closure per sensor sample. For Canvas, maintain spatial data and a hit-test rule separate from paint code. Draw order must match hit-test priority when shapes overlap. Use the same source record for graphic labels and a text list so an accessibility path cannot drift from the visible scene. Do not serialize DOM or pixels as the only saved state.',
    cost='A large SVG scene can incur DOM, style, and accessibility-tree cost per shape; a Canvas scene can shift work to redrawing and custom hit testing. A naïve Canvas hit test scans O(n) shapes for each pointer event, while a spatial index may reduce repeated queries at an update cost. Either approach can be correct for dozens of regions. Benchmark realistic data on the intended device before adding an index or a GPU path. Track input delay, redraw time, memory, and keyboard reachability together.',
    failure='A Canvas prototype draws a region that cannot be selected by keyboard or described to a screen reader. Another SVG build attaches 47 separate listeners but forgets that a mark can overlap another; pointer and keyboard paths select different records. Test empty scene, overlapping geometry, hidden region, zoom, rapid updates, and a large import. Verify the selected ID and accessible description match regardless of whether a user clicks the graphic or chooses the text list.',
    drill='Represent 47 regions as immutable IDs and geometry in a scene array. Render one SVG overlay and one text list from that array. Select the overlapping region 29 through both paths and compare the resulting case ID. Replace the overlay with a Canvas renderer while preserving the same selection contract. Measure redraw and hit-test time for 47 and 620 regions, then decide whether the extra renderer complexity is justified.',
    decision='Select the rendering medium from measured scene density, while the domain model owns identity and meaning.',
    code='function topRegionAt(regions, point) {\n  return regions.slice().reverse().find(region => point.x >= region.left && point.x <= region.right && point.y >= region.top && point.y <= region.bottom)?.id ?? null;\n}\nconsole.log(topRegionAt([{ id: 29, left: 0, right: 47, top: 0, bottom: 62 }], { x: 12, y: 18 }));\n// Output: 29',
    checks=['Graphic and text list select the same region IDs.','Overlap priority matches visual order.','Saved state is structured, not only a bitmap.'], mistakes=['Assuming Canvas remembers drawn objects.','Rendering a graphic without an equivalent control path.','Building a spatial index before measuring actual density.'], related=['web-tech/chart-and-diagram-text-equivalents','web-tech/accessible-feedback-and-keyboard']),
    dict(hub=0, slug='canvas-pixel-ratio-and-pointer-coordinates', title='Canvas Pixel Ratio and Pointer Coordinates', summary='Separate CSS size, backing pixels, and scene space so drawing and hit testing agree.',
    concept='A Canvas has a CSS display size and a bitmap backing size. If those differ, the browser scales pixels; the result can look soft or distorted. A high-density display may need more backing pixels for the same CSS box, but allocating blindly at the full device ratio can multiply memory and drawing work. Pointer coordinates arrive in viewport CSS pixels. The scene may use its own units. A correct editor makes every conversion explicit and updates it when layout, zoom, or device pixel ratio changes.',
    case='The case map has a CSS box 620 units wide, while its backing bitmap is capped for a high-density tablet. Reviewer 47 taps a defect at scene x=29. The app subtracts the element bounds and maps the remaining CSS position into the scene width before hit testing. When the reviewer zooms the browser, the box changes width and the editor recalculates the mapping. It does not reuse a coordinate scale captured at mount. A pointer placed at the right edge never selects a region outside the scene.',
    implementation='Define one scene coordinate system and one conversion function from client coordinates through the current element bounds. Do not mix backing pixel coordinates with hit-test coordinates. Resize the backing bitmap when the display size changes, then reset or reapply the drawing transform because a Canvas size assignment clears its contents and context state. Cap the effective pixel ratio and total bitmap area by an explicit memory budget. Redraw from the structured scene after resize. Test transforms, padding, scroll, device rotation, and zoom before trusting pointer placement.',
    cost='Bitmap allocation grows as width times height times four bytes for a common RGBA surface, before temporary image buffers and compositing overhead. Doubling both pixel dimensions can roughly quadruple that surface cost. Repeated resize also clears and reallocates work. The coordinate conversion is O(1) per pointer event, while redraw cost depends on surface area and mark count. Throttle nonessential pointer previews to frame cadence, but commit the final pointer position accurately. Measure peak memory and tap accuracy on target devices.',
    failure='A prototype multiplies pointer x by devicePixelRatio twice. The mark appears near the tap but the saved geometry lands farther right, especially after zoom. Another build sets canvas.width on every render, erasing the drawing and reset transform. Test a ratio change, resize from 620 to 310 CSS units, scroll position, device rotation, an empty zero-width box, and taps at all four edges. Verify that the same scene point is selected before and after layout changes.',
    drill='Use a 620-unit scene and render it in boxes of 620 and 310 CSS units. Map a pointer at each box midpoint back to scene x=310. Cap a high device ratio according to a 47-megabyte bitmap budget and record actual allocation. Resize the element while a mark is selected, redraw from scene state, and confirm the selected ID remains the same. Repeat with browser zoom rather than assuming a fixed viewport.',
    decision='Treat drawing resolution and interaction coordinates as separate conversions with one tested scene space.',
    code='function sceneX(clientX, left, cssWidth, sceneWidth) {\n  if (cssWidth <= 0) return null;\n  return (clientX - left) * sceneWidth / cssWidth;\n}\nconsole.log(sceneX(185, 30, 310, 620));\n// Output: 310',
    checks=['Midpoint taps map to one scene point at multiple display sizes.','Resize redraws from model state.','Backing allocation obeys a measured cap.'], mistakes=['Applying device pixel ratio to hit testing twice.','Saving coordinates in transient CSS pixels.','Resizing the bitmap on every component render.'], related=['web-tech/performance-budget-and-layout-stability','web-tech/visual-viewport-keyboard-and-focused-input']),
    dict(hub=0, slug='canvas-origin-clean-export-and-private-assets', title='Canvas Origin-Clean Export and Private Assets', summary='Prove an image can be read or exported before promising annotated downloads.',
    concept='A Canvas that draws a cross-origin image without the required approval is no longer origin-clean. The browser can still display it, but reading pixels or exporting the bitmap is blocked. This restriction prevents a page from reading private pixels from another origin. An annotated case export therefore needs a deliberate image-loading path, permissions, and failure behavior. A signed private image URL also has an expiry and revocation boundary; a displayed image is not automatically safe to retain in an editor cache or derived output.',
    case='Reviewer 29 opens private scan 62 and places a mark at region 47. The scan is served through an authorized image route configured for the editor’s origin. The editor can export the annotated bitmap while permission remains valid. A second scan is loaded from an unrelated image host without the required cross-origin response; the browser displays it, but export fails. The UI keeps the marks as structured data and offers an authorized server export instead of reporting that the annotation was saved as an image. On account switch, object URLs and decoded buffers are released.',
    implementation='Decide whether the editor needs pixel reads, export, or only display before selecting an image route. Configure the image request and server response as a matched cross-origin contract; client settings alone cannot grant access. Keep case authorization on the image endpoint and short-lived URLs scoped to the record. Catch export errors and distinguish blocked pixel access from encoder or memory failure. If export is optional, keep a download-independent annotation record. Avoid copying raw private pixels into general logs, telemetry, shared caches, or long-lived browser storage.',
    cost='Decoding and drawing a large scan can expand memory far beyond compressed file size. Exporting a bitmap creates additional encoded data and may block the main thread; a large server render has its own compute and storage cost. Use a bounded resolution, a worker-supported path where appropriate, or a server job with explicit consent and expiry. The privacy cost of a derived image lasts until the derived file is deleted. Measure decode time, export time, peak memory, failed origin-clean attempts, and artifact retention.',
    failure='The UI says export succeeded after toBlob rejected because one watermark image came from a disallowed origin. A second failure writes the annotated private image to a public asset bucket. Test one approved and one unapproved image origin, an expired signed URL, permission revocation, a partial decode, a very large scan, cancellation during export, and account switch. Verify that the annotation model survives export failure and that no derived private asset leaks to a shared cache.',
    drill='Load two scans with the same visible dimensions but different origin permissions. Add the same mark, then attempt pixel read and export. Record which operation fails and show a recoverable path without losing the mark. Expire the authorized URL and request the asset again through current case access. Inspect the resulting download ownership and expiry. Finally clear editor state and check that no object URL or decoded image remains reachable.',
    decision='Make export a separate authorized capability, with a durable annotation record independent of pixel readback.',
    code='function exportChoice(originClean, serverExportAllowed) {\n  return originClean ? "browser" : serverExportAllowed ? "server" : "marks-only";\n}\nconsole.log(exportChoice(false, true));\n// Output: server',
    checks=['Export failure never loses structured marks.','Private derived images have owner and expiry.','A displayed image is not assumed origin-clean.'], mistakes=['Assuming client cross-origin settings alone permit pixel reads.','Logging private canvas pixels after failure.','Saving an export to a public cache by default.'], related=['web-tech/private-asset-download-revocation-and-expiry','web-tech/upload-intake-budgets-and-storage-ownership']),
    dict(hub=0, slug='accessible-graphic-controls-and-text-equivalents', title='Accessible Graphic Controls and Text Equivalents', summary='Expose graphic relationships and actions through labeled controls and a synchronized text representation.',
    concept='A graphic may encode a relationship that cannot be recovered from a label like “inspection map.” The text equivalent must state the relevant regions, values, and actions. An interactive SVG can expose named shapes, but keyboard order, overlap, and focus indication still need design. A Canvas bitmap requires an adjacent or fallback DOM interaction path because pixels are not individual controls. The graphic and text path should address the same underlying record IDs, so an update to severity or geometry cannot leave one representation stale.',
    case='An inspection map shows 47 marks, including region 29 with a high-severity seal split. The companion region list states each mark’s location, severity, and note. Reviewer 47 can select region 29 through the SVG or the list, then use the same edit form. A color change signals severity visually, while a text label and shape cue convey it without color. At 200 percent zoom, the list remains readable even when the graphic requires panning. When a live reading changes, a bounded status announces the meaningful update rather than every pixel redraw.',
    implementation='Define the information task before writing alternative text: identify a defect, compare severity, or edit a mark. Use a short graphic name and a richer structured list when many regions matter. Ensure interactive elements have stable names and visible focus, and provide keyboard equivalents for pointing and dragging. Use one selection reducer for graphic and list inputs. Avoid making every decorative path separately focusable. For a Canvas, supply ordinary buttons and descriptive content outside or within fallback markup, then verify actual assistive-technology behavior on supported browsers.',
    cost='A text list adds DOM nodes proportional to meaningful records, but it can replace expensive custom keyboard handling and exposes content for search and printing. Announcing every sensor frame would overwhelm assistive technology, so summarize only state changes that matter. A large SVG accessibility tree can also become slow if hundreds of incidental paths are exposed. Group decorative shapes and keep actionable regions bounded. Measure task completion with keyboard and screen reader, not only graphics frame rate.',
    failure='A reviewer can see a red region but its list item still says “low severity” after an update. Another implementation makes the entire Canvas one unnamed button; there is no way to select region 29 without a pointer. Test record addition, deletion, overlapping marks, severity change, zoom, high contrast, keyboard-only input, and screen reader reading order. Compare selected IDs and descriptions across paths after each mutation; do not rely on an image title as the only explanation.',
    drill='Build a 47-item scene and companion list from the same records. Select region 29 from the map, then from the list; inspect focus and selected ID. Change severity and verify both views and the status text. Disable color and try the task using labels and outlines. Then disable the graphic entirely and ask a reviewer to find and edit the seal split using only the text representation.',
    decision='Model graphic meaning as records and controls that remain usable when pixels are unavailable.',
    code='function regionLabel(region) {\n  return `Region ${region.id}: ${region.severity} severity, ${region.note}`;\n}\nconsole.log(regionLabel({ id: 29, severity: "high", note: "seal split" }));\n// Output: Region 29: high severity, seal split',
    checks=['Graphic and list use the same record ID and severity.','Every action has a keyboard path.','A meaningful text representation survives graphic failure.'], mistakes=['Using color as the only severity signal.','Making every decorative path focusable.','Treating one generic image label as equivalent to 47 marks.'], related=['web-tech/chart-and-diagram-text-equivalents','web-tech/pointer-gesture-touch-action-and-alternate-control']),
    dict(hub=1, slug='editable-input-composition-and-document-model', title='Editable Input, Composition, and Document Model', summary='Accept browser edits and IME composition without treating the live DOM as the authoritative document.',
    concept='An editable surface receives operations from typing, paste, drag, autofill, spell correction, and input methods. A beforeinput event can describe an intended edit, but not every edit is cancelable or even observed on every platform. An input event reports that the DOM changed. A rich editor therefore needs a normalized document model and a reconciliation path from the live editing surface. Composition is a multi-step input session; rewriting the DOM on each intermediate character can break languages that use an IME.',
    case='Reviewer 29 writes a case note containing a heading and a paragraph. An IME begins composing a place name. The editor keeps the provisional text visible without converting each keystroke into a committed document transaction. When composition ends, it normalizes the resulting block and records one logical edit. A spell correction later changes a word through a browser path the editor did not cancel in beforeinput; input reconciliation updates the model. The server sees a versioned, allowed document structure, not arbitrary DOM markup copied from the browser.',
    implementation='Choose an explicit schema for blocks and marks. Give each block a stable ID and define allowed operations: insert text, split paragraph, apply emphasis, remove block. Observe beforeinput where useful, but reconcile on input because the former may be absent or non-cancelable. Track composition start and end and defer destructive normalization until the session settles. Validate incoming document transactions and limit size and nesting. Serialize the model to a safe representation for storage; render it through a controlled component or maintained sanitization boundary. Test multiple input methods and mobile keyboards.',
    cost='A model transform can be O(length of the affected block) rather than O(entire document) if operations are scoped. Full DOM serialization on every keypress can become O(n) and move the caret unexpectedly. Composition handling adds state and test surface but prevents lost characters. A custom rich editor is costly to maintain across browsers; use a plain textarea if headings and marks are not a real product need. Measure typing latency, reconciliation frequency, document size, and input methods used in the target audience.',
    failure='The editor cancels every beforeinput event, including an IME path it does not understand, and reviewer 29 cannot enter the place name. Another build trusts the DOM after a spell correction and saves unsupported nested markup. Test composition, paste, drag, autocorrect, mobile dictation, undo, empty document, 47 large paragraphs, and focus after a model update. Confirm the saved representation conforms to the schema and the visible text exactly matches the user’s committed input.',
    drill='Define heading and paragraph blocks with stable IDs. Feed an insert-text transaction, a composition sequence, and a spell correction into the editor. Compare the model with the visible surface after each committed step. Try to insert an unsupported element and verify it is normalized or rejected without losing surrounding text. Run the same note in a plain textarea to decide whether the added editor complexity serves an actual task.',
    decision='Treat the browser as an input source and keep one validated document model as the saved authority.',
    code='function mayNormalize(composing, inputCommitted) {\n  return !composing && inputCommitted;\n}\nconsole.log(mayNormalize(true, true));\n// Output: false',
    checks=['IME composition survives intermediate updates.','Input reconciliation covers uncancelable edits.','Saved blocks obey an explicit schema.'], mistakes=['Assuming every beforeinput is cancelable.','Serializing arbitrary live DOM as the document.','Rebuilding the entire editable surface on each keystroke.'], related=['web-tech/forms-and-data-entry-workflows','web-tech/dom-sinks-and-trusted-content']),
    dict(hub=1, slug='selection-bookmarks-and-transaction-mapping', title='Selection Bookmarks and Transaction Mapping', summary='Represent caret and range positions in model coordinates that survive DOM replacement.',
    concept='A browser selection identifies DOM nodes and offsets. Those nodes can disappear when a renderer replaces a paragraph, a collaborative update inserts text, or a paste is normalized. Saving a Range object alone is therefore not a durable caret strategy. A document editor needs a model bookmark, such as block ID and text offset, and a rule for mapping it through each transaction. Selection direction can matter for shift-selection. A deleted block needs an explicit fallback position rather than a stale node reference.',
    case='Reviewer 47 selects characters 29 through 47 in a case note and applies emphasis. The document transform splits text runs, so the original text node is replaced. The editor maps the selection to block 62 offsets and restores it after rendering. Another reviewer inserts five characters before the range; the bookmark shifts. If the whole block is deleted, focus returns to the nearest surviving editable block. The browser’s visible caret and model offsets remain consistent after undo and after a remote revision arrives.',
    implementation='Store selection as anchor and focus positions in the document model, not just start and end DOM nodes. For each insert, delete, split, and merge transaction, define a mapping from old positions to new positions. Use stable block IDs and clamp offsets to valid text length. Convert DOM selection to model positions at the input boundary, then restore DOM selection after the committed render. Avoid collapsing a backward selection accidentally. During composition, minimize selection restoration unless the browser requires it. Test nested formatting, empty blocks, bidirectional text, and a node removed by remote change.',
    cost='Mapping a position through one local operation can be O(1) or proportional to affected blocks; scanning the entire DOM after every key can become O(n). Long histories of transactions may require periodic checkpoints if bookmarks need replay. Holding stale Range objects can retain detached nodes and increase memory. Caret correctness is a product cost, not a cosmetic detail: when it fails, users type into the wrong place. Measure edit latency and selection restoration failures across keyboard, touch, and assistive technologies.',
    failure='The editor holds a Range pointing to a text node that was replaced when emphasis was applied. The next character appears at the start of the note. Another path maps only the start offset and reverses a backward selection. Test insert before selection, delete inside selection, split and join blocks, undo, remote insertion, block deletion, emoji and combining characters, and right-to-left text. Define offsets in one unit and do not mix UTF-16 DOM offsets with user-perceived grapheme counts without conversion.',
    drill='Create a note with block 62 and a model selection from offsets 29 to 47. Apply emphasis, insert five code units before the range, and map both positions. Delete the block and verify the documented fallback. Repeat with a backward selection and an emoji before the caret. Inspect the browser selection after each render rather than assuming the model bookmark restored correctly.',
    decision='Map selections through model transactions and use DOM Range only as a temporary interface.',
    code='function mapOffsetAfterInsert(offset, insertAt, length) {\n  return offset >= insertAt ? offset + length : offset;\n}\nconsole.log(mapOffsetAfterInsert(47, 29, 5));\n// Output: 52',
    checks=['Caret survives a formatting render.','Selection direction remains intact.','Deleted blocks have a deterministic fallback.'], mistakes=['Persisting a Range after its nodes are replaced.','Mixing code-unit and grapheme offsets.','Restoring only the start of a backward selection.'], related=['web-tech/asynchronous-field-validation-races','web-tech/complex-accessible-interactions']),
    dict(hub=1, slug='paste-import-sanitization-and-link-policy', title='Paste Import, Sanitization, and Link Policy', summary='Convert clipboard fragments into a narrow document schema before they can reach storage or rendered HTML.',
    concept='A paste can contain plain text, rich HTML, images, links, and formatting from another application. The clipboard is untrusted input even when a user initiates the action. A rich editor should parse only the content classes its document model supports, normalize them, and reject unsafe attributes and URL schemes. This is distinct from output safety: the server must validate stored content and the renderer must use a maintained safe HTML policy if it emits markup. A client-side paste filter alone cannot protect other write paths.',
    case='Reviewer 29 pastes a formatted inspection note copied from a supplier portal. The fragment contains a heading, two paragraphs, a link, a tracking image, and inline event code. The editor retains the text and allowed emphasis, validates the link destination under a product policy, drops the tracking image and event attribute, and previews the normalized result before save. The API validates the document structure again. When another reviewer opens the note, the controlled renderer produces only allowed nodes. The original clipboard HTML is never stored as the case record.',
    implementation='Define an allowlist of document nodes and attributes, including a URL policy for links and media. Prefer converting clipboard HTML into the editor model rather than inserting raw HTML into the live DOM. If plain text meets the task, paste text only and avoid a rich HTML path entirely. Sanitize at a maintained boundary and validate again server-side, because clients are bypassable. Render through safe components or a maintained sanitizer configured for the exact output context. Do not modify sanitized markup afterward in a way that reintroduces unsafe content.',
    cost='Parsing and normalization are O(n) in pasted fragment size, so cap bytes and node depth before processing. A large copied page can freeze a main-thread editor and fill undo history with a single action. Image handling adds upload, scan, ownership, and expiry costs; do not accept it by accident through a paste event. Keep a visible rejection or flattening rule for unsupported formatting. Monitor paste failures and normalized-node counts without logging the private clipboard text.',
    failure='The editor strips scripts on paste but stores the original HTML beside the model for later export; a preview path then renders the unsafe copy. Another build allows a harmless-looking link whose scheme can execute when clicked. Test script and event attributes, unusual URL schemes, nested tables, a 47-megabyte fragment, broken markup, pasted images, and content submitted directly to the API without using the editor. Ensure stored and exported forms follow one policy and the case note remains readable if formatting is dropped.',
    drill='Paste a fragment with one heading, two paragraphs, an approved link, an image, and an event attribute. Compare the parsed model with the approved schema and explain every removed node. Submit the same unsafe payload directly to the API; it must be rejected or normalized under the server contract. Reload and export the stored note, then inspect that the safe representation is consistent in both paths. Cap a large fragment before expensive DOM work.',
    decision='Normalize clipboard content into a small model and enforce the same safety policy at save and render boundaries.',
    code='function allowedNoteNode(type) {\n  return new Set(["paragraph", "heading", "text", "emphasis", "link"]).has(type);\n}\nconsole.log(allowedNoteNode("script"));\n// Output: false',
    checks=['Direct API writes face the same document policy.','Unsafe links and attributes do not survive normalization.','Private clipboard bytes stay out of telemetry.'], mistakes=['Treating user-initiated paste as trusted.','Keeping original unsafe HTML for another render path.','Accepting pasted images without an asset lifecycle.'], related=['web-tech/output-escaping-and-csp','web-tech/clipboard-and-share-activation-fallbacks']),
    dict(hub=1, slug='undo-history-autosave-and-revision-conflicts', title='Undo History, Autosave, and Revision Conflicts', summary='Bound local edit history and save a document through conditional revisions without erasing newer work.',
    concept='Undo reverts a local editing transaction; it does not reverse a server write or another reviewer’s change. A usable history groups related typing into meaningful steps, records selection before and after each step, and invalidates redo when a new branch is created. Autosave adds another timeline: local draft, in-flight request, acknowledged server revision, and a possible conflict. The editor must separate these states so a late response cannot mark a newer draft as saved. A conditional revision at the server protects against lost updates.',
    case='Reviewer 47 edits case note 62 at revision 29. Three keystrokes become one undo step. Autosave request A carries revision 29 and document generation 6. While it runs, reviewer 47 adds another sentence, producing generation 7. Request A succeeds at server revision 30, but the editor remains dirty because generation 7 was not in that request. Reviewer 29 changes the same note before the next save; request B receives a conflict. The editor retains both local text and the newer server version for review, rather than overwriting either silently.',
    implementation='Represent edits as transactions with inverse information and model selection, or bounded snapshots for small documents. Limit history by count and bytes, grouping nearby typing without merging separate commands. Invalidate redo after a new edit following undo. Give each autosave payload a local generation, base server revision, and idempotency key. On response, clear dirty state only if the acknowledged generation still equals the current document generation. A conflict should present local and remote versions with an explicit resolution path; avoid automatic merge when rich structure or permissions make it ambiguous. Clean private drafts on account switch.',
    cost='Full snapshots cost O(document size times history depth); transaction history can be smaller but requires careful inverse mapping. Debounced autosave reduces request volume but raises the window of unsaved local work. Conditional writes add conflicts that require user time, yet prevent silent loss. A large rich note can exceed local storage quota or make every snapshot expensive. Track undo bytes, save latency, dirty duration, conflict frequency, and draft recovery success without collecting note text.',
    failure='Request A succeeds and the UI shows “saved” even though generation 7 has not been sent; the reviewer closes the tab and loses a sentence. Another path presses undo after a server conflict and accidentally reverts the remote version instead of the local edit. Test out-of-order save responses, repeated idempotency keys, offline editing, undo then new typing, account switch, storage quota failure, and concurrent reviewers. Confirm that every state label corresponds to a specific local generation and server revision.',
    drill='Start with revision 29 and generate two edits while the first autosave is pending. Resolve its response, then verify the editor remains dirty. Simulate a conflict on the second save and preserve both versions. Undo one local grouped step and add a new edit; redo must no longer replay the old branch. Fill history until its byte cap is reached, then inspect whether recent edits and selection remain recoverable.',
    decision='Tie undo to local transactions and autosave acknowledgment to the exact generation sent.',
    code='function saveAcknowledgesCurrent(sentGeneration, currentGeneration) {\n  return sentGeneration === currentGeneration;\n}\nconsole.log(saveAcknowledgesCurrent(6, 7));\n// Output: false',
    checks=['Late save responses cannot clear newer dirty state.','Undo history is bounded and scoped to local edits.','Conflicts preserve local and server versions.'], mistakes=['Treating undo as server rollback.','Marking the latest draft saved after an older response.','Keeping private note history after account switch.'], related=['web-tech/autosave-draft-recovery-and-conflicts','web-tech/conditional-writes-and-lost-update-prevention']),
]

assert len(hubs) == 2 and len(topics) == 8
for number, hub in enumerate(hubs):
    path = hub['path']
    assert path not in by_path
    entry = copy.deepcopy(by_path['web-tech/production-signals-and-incident-decisions'])
    entry.update(id=str(uuid.uuid5(uuid.NAMESPACE_URL, 'aitrove:' + path)), path=path, title=hub['title'], summary=hub['summary'], sort_order=2910 + number, created_at=stamp, updated_at=stamp, published_at=stamp)
    entry['data'] = {'subject_root':'web-tech/web-technology','section_path':path,'content_format':'html','seo_ready':False,'modules':[],'resource_tabs':[{'title':'Web Development','path':'web-tech/web-technology'},{'title':'Projects','path':'web-tech/web-technology/project'},{'title':'Quizzes','path':'web-tech/quizzes'}]}
    entries.append(entry)
    by_path[path] = entry

for number, topic in enumerate(topics):
    path = 'web-tech/' + topic['slug']
    assert path not in by_path
    subprocess.run(['node','--check','--input-type=module'], input=topic['code'], text=True, capture_output=True, check=True)
    entry = copy.deepcopy(by_path['web-tech/trace-context-across-request-and-job'])
    entry.update(id=str(uuid.uuid5(uuid.NAMESPACE_URL, 'aitrove:' + path)), path=path, title=topic['title'], summary=topic['summary'], sort_order=2920 + number, created_at=stamp, updated_at=stamp, published_at=stamp)
